-- 0a. Thai timezone (session + database default)
SET TIME ZONE 'Asia/Bangkok';  -- now()/DEFAULT/display in Thai time (UTC+7); TIMESTAMPTZ still stores the absolute instant
-- Database default timezone = Asia/Bangkok (new connections). Needs DB owner/superuser; otherwise WARNING (ask the DBA).
DO $$ BEGIN
    EXECUTE format('ALTER DATABASE %I SET timezone TO %L', current_database(), 'Asia/Bangkok');
EXCEPTION WHEN insufficient_privilege THEN
    RAISE WARNING 'no privilege to ALTER DATABASE % SET timezone — set it manually (session timezone is Asia/Bangkok)', current_database();
END $$;

-- 0b. modified_date_time trigger function (audit standard)
CREATE OR REPLACE FUNCTION set_modified_date_time() RETURNS trigger
    LANGUAGE plpgsql AS $$
BEGIN
    NEW.modified_date_time := now();
    RETURN NEW;
END;
$$;
COMMENT ON FUNCTION set_modified_date_time() IS 'BEFORE UPDATE trigger (ทุกตาราง): ตั้ง modified_date_time = now() อัตโนมัติ; modified_by แอปเป็นผู้ตั้ง (ecommerce schema v3 audit standard)';

