-- ---------------------------------------------------------------------------
-- shop_customers
-- ---------------------------------------------------------------------------
CREATE TABLE shop_customers (
    id UUID DEFAULT gen_random_uuid() NOT NULL,
    shop_id UUID NOT NULL,
    user_id UUID,
    customer_code VARCHAR(40),
    display_name VARCHAR(150) NOT NULL,
    phone VARCHAR(30),
    email VARCHAR(255),
    default_address JSONB,
    internal_note TEXT,
    source VARCHAR(20) DEFAULT 'MANUAL' NOT NULL,
    status VARCHAR(20) DEFAULT 'ACTIVE' NOT NULL,
    deleted_at TIMESTAMPTZ,
    created_date_time TIMESTAMPTZ DEFAULT now() NOT NULL,
    created_by UUID,
    modified_date_time TIMESTAMPTZ DEFAULT now() NOT NULL,
    modified_by UUID,
    CONSTRAINT pk_shop_customers PRIMARY KEY (id),
    CONSTRAINT uq_shop_customers_shop_id_customer_code UNIQUE (shop_id, customer_code),
