COMMENT ON COLUMN merchant_order_confirmations.modified_by IS 'audit: ผู้แก้ไขล่าสุด — logical ref users.id (ไม่มี FK); แอปเป็นผู้ตั้งค่า; NULL = system/job/webhook';
