CREATE TABLE payment_proofs (
    id UUID DEFAULT gen_random_uuid() NOT NULL,
    payment_id UUID NOT NULL,
    order_id UUID NOT NULL,
    shop_id UUID NOT NULL,
    uploaded_by_user_id UUID,
    media_file_id UUID,
    proof_type VARCHAR(30) DEFAULT 'SLIP' NOT NULL,
    reference_no VARCHAR(120),
    amount_declared NUMERIC(18,2),
    currency CHAR(3) DEFAULT 'THB' NOT NULL,
    transferred_at TIMESTAMPTZ,
    status VARCHAR(30) DEFAULT 'PENDING_REVIEW' NOT NULL,
    verified_by UUID,
    verified_at TIMESTAMPTZ,
    reject_reason VARCHAR(500),
    created_date_time TIMESTAMPTZ DEFAULT now() NOT NULL,
    created_by UUID,
    modified_date_time TIMESTAMPTZ DEFAULT now() NOT NULL,
    modified_by UUID,
    CONSTRAINT pk_payment_proofs PRIMARY KEY (id),
    CONSTRAINT ck_payment_proofs_proof_type CHECK (proof_type IN ('SLIP', 'GATEWAY_RECEIPT')),
    CONSTRAINT ck_payment_proofs_status CHECK (status IN ('PENDING_REVIEW', 'VERIFIED', 'REJECTED'))
);

CREATE INDEX ix_payment_proofs_payment_id ON payment_proofs (payment_id);  -- desc payment_proofs.payment_id 'idx'
CREATE INDEX ix_payment_proofs_shop_id_status_created_date_time ON payment_proofs (shop_id, status, created_date_time);  -- desc payment_proofs.shop_id
