-- ---------------------------------------------------------------------------
-- shipments
-- ---------------------------------------------------------------------------
CREATE TABLE shipments (
    id UUID DEFAULT gen_random_uuid() NOT NULL,
    order_id UUID NOT NULL,
    shop_id UUID NOT NULL,
    shipping_method_id UUID,
    status VARCHAR(40) DEFAULT 'READY_TO_PACK' NOT NULL,
    carrier_code VARCHAR(50),
    tracking_number VARCHAR(100),
    label_url VARCHAR(700),
    packed_at TIMESTAMPTZ,
    picked_up_at TIMESTAMPTZ,
    dispatched_at TIMESTAMPTZ,
    delivered_at TIMESTAMPTZ,
    last_tracking_event_at TIMESTAMPTZ,
    packed_by UUID,
    dispatched_by UUID,
    oms_external_shipment_id VARCHAR(100),
    oms_sync_status VARCHAR(30) DEFAULT 'NOT_SYNCED' NOT NULL,
    oms_synced_at TIMESTAMPTZ,
    created_date_time TIMESTAMPTZ DEFAULT now() NOT NULL,
    created_by UUID,
    modified_date_time TIMESTAMPTZ DEFAULT now() NOT NULL,
    modified_by UUID,
    CONSTRAINT pk_shipments PRIMARY KEY (id),
    CONSTRAINT ck_shipments_status CHECK (status IN ('READY_TO_PACK', 'PACKING', 'PACKED', 'DISPATCHED', 'IN_TRANSIT', 'OUT_FOR_DELIVERY', 'DELIVERED', 'DELIVERY_FAILED', 'CANCELLED', 'RETURNED')),
    CONSTRAINT ck_shipments_oms_sync_status CHECK (oms_sync_status IN ('NOT_SYNCED', 'PENDING', 'SYNCED', 'FAILED', 'STALE', 'IGNORED'))
);

CREATE INDEX ix_shipments_tracking_number ON shipments (tracking_number);  -- desc shipments.tracking_number 'idx'
CREATE INDEX ix_shipments_order_id ON shipments (order_id);  -- FK
CREATE INDEX ix_shipments_shop_id ON shipments (shop_id);  -- FK
CREATE INDEX ix_shipments_shipping_method_id ON shipments (shipping_method_id);  -- FK
CREATE INDEX ix_shipments_packed_by ON shipments (packed_by);  -- FK
CREATE INDEX ix_shipments_dispatched_by ON shipments (dispatched_by);  -- FK
COMMENT ON TABLE shipments IS '[Shipping] งานจัดส่ง';
COMMENT ON COLUMN shipments.id IS 'งานจัดส่ง';
COMMENT ON COLUMN shipments.status IS 'READY_TO_PACK|PACKING|PACKED|DISPATCHED|IN_TRANSIT|OUT_FOR_DELIVERY|DELIVERED|DELIVERY_FAILED|CANCELLED|RETURNED (v3 +OUT_FOR_DELIVERY, DELIVERY_FAILED) [CHECK enum: shipment_status]';
COMMENT ON COLUMN shipments.tracking_number IS 'idx';
COMMENT ON COLUMN shipments.label_url IS 'URL ใบปะหน้า (OMS/carrier)';
