    status VARCHAR(30) DEFAULT 'PENDING' NOT NULL,
    provider_refund_id VARCHAR(120),
    idempotency_key VARCHAR(120) NOT NULL,
    initiated_by UUID,
    reason VARCHAR(500),
    created_date_time TIMESTAMPTZ DEFAULT now() NOT NULL,
    created_by UUID,
    modified_date_time TIMESTAMPTZ DEFAULT now() NOT NULL,
    modified_by UUID,
    CONSTRAINT pk_refunds PRIMARY KEY (id),
    CONSTRAINT uq_refunds_idempotency_key UNIQUE (idempotency_key),
    CONSTRAINT ck_refunds_amount CHECK (amount > 0),
    CONSTRAINT ck_refunds_status CHECK (status IN ('PENDING', 'SUCCEEDED', 'FAILED'))
);

