-- ---------------------------------------------------------------------------
CREATE TABLE background_jobs (
    id UUID DEFAULT gen_random_uuid() NOT NULL,
    shop_id UUID,
    job_type VARCHAR(80) NOT NULL,
    schema_version INTEGER DEFAULT 1 NOT NULL,
    status VARCHAR(30) DEFAULT 'QUEUED' NOT NULL,
    priority SMALLINT DEFAULT 5 NOT NULL,
    resource_type VARCHAR(40),
    resource_id UUID,
    idempotency_key VARCHAR(120),
    correlation_id VARCHAR(64),
    request_id VARCHAR(64),
    payload_ref JSONB,
    attempt_count INTEGER DEFAULT 0 NOT NULL,
    max_attempts INTEGER DEFAULT 4 NOT NULL,
    lease_owner VARCHAR(80),
    lease_expires_at TIMESTAMPTZ,
    cancel_requested_at TIMESTAMPTZ,
    progress JSONB,
    result_summary JSONB,
    error_code VARCHAR(64),
    error_message VARCHAR(500),
    started_at TIMESTAMPTZ,
    finished_at TIMESTAMPTZ,
    requested_by_user_id UUID,
    auth_context VARCHAR(20),
    required_permission VARCHAR(80),
    permission_version_at_request INTEGER,
    policy_version VARCHAR(20),
    result_file_id UUID,
    created_date_time TIMESTAMPTZ DEFAULT now() NOT NULL,
    created_by UUID,
    modified_date_time TIMESTAMPTZ DEFAULT now() NOT NULL,
    modified_by UUID,
    CONSTRAINT pk_background_jobs PRIMARY KEY (id),
    CONSTRAINT uq_background_jobs_idempotency_key UNIQUE (idempotency_key),
    CONSTRAINT ck_background_jobs_status CHECK (status IN ('QUEUED', 'RUNNING', 'RETRYING', 'SUCCEEDED', 'PARTIALLY_SUCCEEDED', 'FAILED', 'CANCELLED')),
    CONSTRAINT ck_background_jobs_auth_context CHECK (auth_context IN ('ACCOUNT', 'SHOP', 'PLATFORM', 'SERVICE'))
);

CREATE INDEX ix_background_jobs_shop_id ON background_jobs (shop_id);  -- FK
CREATE INDEX ix_background_jobs_requested_by_user_id ON background_jobs (requested_by_user_id);  -- FK
