-- =============================================================================
-- authz data steps (Flyway V3 only)
-- =============================================================================
-- users.role deprecation — step 1: copy legacy ADMIN users to platform_roles (keep users.role; DROP in a later migration)
INSERT INTO platform_roles (user_id, role, granted_at, grant_reason)
SELECT u.id, 'PLATFORM_ADMIN', now(), 'V3 backfill from legacy users.role=ADMIN'
  FROM users u
 WHERE u.role = 'ADMIN'
   AND NOT EXISTS (SELECT 1 FROM platform_roles pr WHERE pr.user_id = u.id AND pr.revoked_at IS NULL);

-- authz catalog (READ-ONLY reference; enforcement stays in code) — policy_version 1.0:
--   10 roles / 62 permissions / 150 role→permission mappings (Role and Permission Matrix v1.1)
--   Idempotent: upsert by code (UPDATE only when something changed), mappings ON CONFLICT DO NOTHING,
--   mappings no longer in the catalog are deleted, permissions no longer in the catalog are deactivated (kept for audit history).
INSERT INTO auth_roles (code, context, name_th, description_th, is_assignable, sort_order, policy_version) VALUES
    ('GUEST', 'PUBLIC', 'ผู้เยี่ยมชม', 'ผู้ใช้ที่ยังไม่เข้าสู่ระบบ — ดูหน้าร้าน/สินค้าสาธารณะ', false, 10, '1.0'),
    ('BUYER', 'ACCOUNT', 'ผู้ซื้อ', 'บัญชีผู้ซื้อที่เข้าสู่ระบบ — ตะกร้า ชำระเงิน ออเดอร์ของตนเอง', false, 20, '1.0'),
    ('APPLICANT', 'APPLICANT', 'ผู้สมัครเปิดร้าน', 'เจ้าของใบสมัครเปิดร้าน — จัดการใบสมัครของตนเอง', false, 30, '1.0'),
    ('STORE_OWNER', 'STORE', 'เจ้าของร้าน', 'ทุกสิทธิ์ในร้าน รวมปิดร้านและโอนเจ้าของ', true, 40, '1.0'),
    ('STORE_ADMIN', 'STORE', 'แอดมินร้าน', 'จัดการร้านและทีม ยกเว้นอำนาจเฉพาะเจ้าของ', true, 50, '1.0'),
    ('STORE_MANAGER', 'STORE', 'ผู้จัดการร้าน', 'สินค้า สต็อก ออเดอร์ รายงาน', true, 60, '1.0'),
    ('STORE_SALES', 'STORE', 'ฝ่ายขาย', 'ลูกค้าและออเดอร์ก่อนชำระ', true, 70, '1.0'),
    ('STORE_WAREHOUSE', 'STORE', 'คลังสินค้า', 'แพ็ก จัดส่ง และปรับสต็อก', true, 80, '1.0'),
    ('STORE_VIEWER', 'STORE', 'ผู้ดูอย่างเดียว', 'อ่านอย่างเดียว ปกปิด PII', true, 90, '1.0'),
    ('PLATFORM_ADMIN', 'PLATFORM', 'ผู้ดูแลแพลตฟอร์ม', 'ทีมดูแลเว็บ — แต่งตั้งภายในเท่านั้น', true, 100, '1.0')
ON CONFLICT (code) DO UPDATE SET context = EXCLUDED.context, name_th = EXCLUDED.name_th, description_th = EXCLUDED.description_th,
    is_assignable = EXCLUDED.is_assignable, sort_order = EXCLUDED.sort_order, policy_version = EXCLUDED.policy_version
WHERE (auth_roles.context, auth_roles.name_th, auth_roles.description_th, auth_roles.is_assignable, auth_roles.sort_order, auth_roles.policy_version)
      IS DISTINCT FROM (EXCLUDED.context, EXCLUDED.name_th, EXCLUDED.description_th, EXCLUDED.is_assignable, EXCLUDED.sort_order, EXCLUDED.policy_version);

INSERT INTO auth_permissions (code, module, scope, description_th, doc_section, is_active, policy_version) VALUES
