ON CONFLICT (code) DO UPDATE SET module = EXCLUDED.module, scope = EXCLUDED.scope, description_th = EXCLUDED.description_th,
    doc_section = EXCLUDED.doc_section, is_active = EXCLUDED.is_active, policy_version = EXCLUDED.policy_version
WHERE (auth_permissions.module, auth_permissions.scope, auth_permissions.description_th, auth_permissions.doc_section, auth_permissions.is_active, auth_permissions.policy_version)
      IS DISTINCT FROM (EXCLUDED.module, EXCLUDED.scope, EXCLUDED.description_th, EXCLUDED.doc_section, EXCLUDED.is_active, EXCLUDED.policy_version);

UPDATE auth_permissions SET is_active = false
 WHERE is_active AND code NOT IN ('SHOP_READ', 'SHOP_UPDATE', 'SHOP_CLOSE', 'OWNERSHIP_TRANSFER', 'USER_READ', 'USER_INVITE', 'USER_ROLE_UPDATE', 'USER_REMOVE', 'PRODUCT_READ', 'PRODUCT_CREATE', 'PRODUCT_UPDATE', 'PRODUCT_ARCHIVE', 'PRODUCT_IMPORT', 'INVENTORY_READ', 'INVENTORY_RECEIVE', 'INVENTORY_ADJUST', 'CUSTOMER_READ', 'CUSTOMER_PII_READ', 'CUSTOMER_CREATE', 'CUSTOMER_UPDATE', 'ORDER_READ', 'ORDER_CREATE', 'ORDER_UPDATE', 'ORDER_CANCEL', 'ORDER_REFUND', 'SHIPMENT_READ', 'SHIPMENT_ADDRESS_READ', 'SHIPMENT_PACK', 'SHIPMENT_DISPATCH', 'SHIPMENT_UPDATE', 'REPORT_READ', 'REPORT_EXPORT', 'ORDER_EXPORT', 'AUDIT_READ', 'PLATFORM_SHOP_READ', 'PLATFORM_SHOP_SUSPEND', 'PLATFORM_SHOP_RESTORE', 'PLATFORM_APPLICATION_READ', 'PLATFORM_APPLICATION_REVIEW', 'PLATFORM_ACCOUNT_READ', 'PLATFORM_ACCOUNT_SUSPEND', 'PLATFORM_ACCOUNT_RESTORE', 'PLATFORM_SETTING_UPDATE', 'PLATFORM_AUDIT_READ', 'SHOP_APPLICATION_CREATE', 'SHOP_APPLICATION_READ', 'SHOP_APPLICATION_UPDATE', 'SHOP_APPLICATION_FILE_UPLOAD', 'SHOP_APPLICATION_SUBMIT', 'SHOP_APPLICATION_WITHDRAW', 'CATALOG_READ', 'BUYER_PROFILE_READ', 'BUYER_PROFILE_UPDATE', 'BUYER_ADDRESS_READ', 'BUYER_ADDRESS_UPDATE', 'CART_READ', 'CART_UPDATE', 'CHECKOUT_CREATE', 'BUYER_PAYMENT_CREATE', 'BUYER_ORDER_READ', 'BUYER_ORDER_CANCEL', 'BUYER_SHIPMENT_READ');

